import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.nkraVhM_.js";var i=JSON.parse(`{"title":"使用指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/usage.md","filePath":"zh-TW/guide/usage.md","lastUpdated":1793173149000}`),a={name:`zh-TW/guide/usage.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="使用指南" tabindex="-1">使用指南 <a class="header-anchor" href="#使用指南" aria-label="Permalink to “使用指南”">​</a></h1><h2 id="基本玩法" tabindex="-1">基本玩法 <a class="header-anchor" href="#基本玩法" aria-label="Permalink to “基本玩法”">​</a></h2><h3 id="目標" tabindex="-1">目標 <a class="header-anchor" href="#目標" aria-label="Permalink to “目標”">​</a></h3><p>填滿 9×9 的方格，讓每一<strong>列</strong>、每一<strong>欄</strong>，以及九個 3×3 <strong>區塊</strong>都恰好包含 1 到 9 的所有數字各一次。任何一個單元內都不得重複。</p><h3 id="怎麼玩" tabindex="-1">怎麼玩 <a class="header-anchor" href="#怎麼玩" aria-label="Permalink to “怎麼玩”">​</a></h3><ul><li><strong>填入數字</strong>：點一下或按一下空白格，然後點選畫面底部數字鍵盤上的數字。</li><li><strong>鉛筆筆記（候選數）</strong>：切換鉛筆模式後，點選格子即可寫下小小的候選數字，方便記錄各種可能性。</li><li><strong>擦除</strong>：點一下「擦除」按鈕可清除格子的數值（在鉛筆模式下則清除鉛筆筆記）。</li><li><strong>提示</strong>：點一下「提示」可揭曉一個正確格子的數值。</li><li><strong>復原</strong>：點一下「復原」可撤回上一步（支援完整的復原歷程）。</li></ul><h3 id="難度等級" tabindex="-1">難度等級 <a class="header-anchor" href="#難度等級" aria-label="Permalink to “難度等級”">​</a></h3><p>每個難度等級決定遊戲開始時已預先填入的格子（已知格）數量：</p><table tabindex="0"><thead><tr><th>等級</th><th>已知格</th><th>適合對象</th></tr></thead><tbody><tr><td>簡單</td><td>45</td><td>初學者與快速來一局</td></tr><tr><td>中等</td><td>36</td><td>休閒玩家</td></tr><tr><td>困難</td><td>31</td><td>經常解題的玩家</td></tr><tr><td>專家</td><td>27</td><td>經驗豐富的玩家</td></tr><tr><td>大師</td><td>24</td><td>解謎高手</td></tr></tbody></table><p><img src="/screenshot-mac-main.png" alt="Sudoku 在 Mac 上的遊戲盤面"></p><h2 id="遊戲操作" tabindex="-1">遊戲操作 <a class="header-anchor" href="#遊戲操作" aria-label="Permalink to “遊戲操作”">​</a></h2><h3 id="iphone-ipad" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ul><li><strong>點一下</strong>空白格即可選取</li><li><strong>點選數字鍵</strong>上的數字即可填入</li><li><strong>切換鉛筆模式</strong>可輸入或擦除候選筆記</li><li><strong>使用擦除</strong>可清除格子內容</li><li><strong>使用提示</strong>在卡關時取得協助</li><li><strong>使用復原</strong>可收回剛才的步驟</li></ul><h3 id="mac" tabindex="-1">Mac <a class="header-anchor" href="#mac" aria-label="Permalink to “Mac”">​</a></h3><ul><li><strong>按一下左鍵</strong>選取空白格</li><li><strong>按下數字鍵（1–9）</strong>，或點選畫面上的數字鍵盤即可填入</li><li><strong>切換鉛筆模式</strong>可輸入候選筆記</li><li><strong>鍵盤快速鍵</strong>： <ul><li><code>⌘N</code> — 新遊戲</li><li><code>⌘Z</code> — 復原</li><li><code>⌘1</code> 到 <code>⌘5</code> — 以各難度等級開始新遊戲</li></ul></li></ul><p><img src="/screenshot-iphone-main.png" alt="Sudoku 在 iPhone 上的首頁畫面"></p><p><img src="/screenshot-ipad-main.png" alt="Sudoku 在 iPad 上的首頁畫面"></p><h2 id="智慧功能" tabindex="-1">智慧功能 <a class="header-anchor" href="#智慧功能" aria-label="Permalink to “智慧功能”">​</a></h2><h3 id="鉛筆筆記系統" tabindex="-1">鉛筆筆記系統 <a class="header-anchor" href="#鉛筆筆記系統" aria-label="Permalink to “鉛筆筆記系統”">​</a></h3><p>開啟鉛筆模式後，你可以在空白格中寫下小小的候選數字。這套智慧鉛筆系統會：</p><ul><li><strong>自動清除相關格子的鉛筆筆記</strong>：當你填入確定數字時，同一列、同一欄與同一區塊內所有格子上該數字的鉛筆筆記都會自動移除。</li><li><strong>逐格切換</strong>：隨時可在輸入模式與鉛筆模式之間切換。</li></ul><h3 id="錯誤檢查" tabindex="-1">錯誤檢查 <a class="header-anchor" href="#錯誤檢查" aria-label="Permalink to “錯誤檢查”">​</a></h3><p>可選用的錯誤標示會以紅色顯示填錯的數字，幫助你學習，同時不會洩漏答案。</p><h3 id="每日挑戰" tabindex="-1">每日挑戰 <a class="header-anchor" href="#每日挑戰" aria-label="Permalink to “每日挑戰”">​</a></h3><p>每天都會生成一道全新的大師級題目。你的每日挑戰進度會記錄在「統計資料」中，並以月曆檢視顯示你的連續天數。</p><h3 id="統計資料" tabindex="-1">統計資料 <a class="header-anchor" href="#統計資料" aria-label="Permalink to “統計資料”">​</a></h3><p>追蹤你的數獨歷程：</p><ul><li>總遊戲局數與勝率</li><li>目前連續天數與最佳連續天數</li><li>各難度細部數據：勝場數、最佳時間、平均時間</li><li>附完成標記的每日挑戰月曆</li></ul><p><img src="/screenshot-mac-settings.png" alt="Sudoku 在 Mac 上的統計資料"></p><h2 id="主題" tabindex="-1">主題 <a class="header-anchor" href="#主題" aria-label="Permalink to “主題”">​</a></h2><p>在「設定」中挑選八種漂亮的配色主題：</p><table tabindex="0"><thead><tr><th>主題</th><th>風格</th></tr></thead><tbody><tr><td>經典</td><td>乾淨的白色搭配藍色點綴</td></tr><tr><td>午夜</td><td>深藍色調的深色模式</td></tr><tr><td>紙張</td><td>溫暖的羊皮紙質感</td></tr><tr><td>森林</td><td>自然的綠色調</td></tr><tr><td>海洋</td><td>平靜的海洋藍</td></tr><tr><td>日落</td><td>溫暖的橘色漸層</td></tr><tr><td>薰衣草</td><td>柔和的紫色調</td></tr><tr><td>玫瑰</td><td>優雅的粉紅配色</td></tr></tbody></table><h2 id="icloud-同步" tabindex="-1">iCloud 同步 <a class="header-anchor" href="#icloud-同步" aria-label="Permalink to “iCloud 同步”">​</a></h2><p>當你的裝置已登入 iCloud：</p><ul><li>遊戲存檔會自動同步——可在任何裝置上繼續</li><li>統計資料與設定保持一致</li><li>每日挑戰進度可跨裝置轉移</li><li>需 iOS/iPadOS 16+ 或 macOS 15+</li></ul><h2 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h2><p>連結 Game Center 後可以：</p><ul><li>在<strong>排行榜</strong>上依各難度最佳完成時間與他人較勁</li><li>獲得<strong>成就</strong>：首次解題、簡單／中等／困難／專家／大師通關、完美無瑕（不使用提示、不發生錯誤）</li></ul><h2 id="列印題目-mac" tabindex="-1">列印題目（Mac） <a class="header-anchor" href="#列印題目-mac" aria-label="Permalink to “列印題目（Mac）”">​</a></h2><p>在 Mac 上，可直接從 App 列印題目：</p><ol><li>從工具列開啟 <strong>列印</strong> 對話框</li><li>選擇難度等級（簡單到大師）</li><li>視需要切換「包含答案」</li><li>按一下 <strong>列印</strong></li></ol><p>最適合用紙筆離線解題！</p><h2 id="音效" tabindex="-1">音效 <a class="header-anchor" href="#音效" aria-label="Permalink to “音效”">​</a></h2><p>Sudoku 內建細緻的音效：</p><ul><li>填入數字的確認音</li><li>提示揭曉</li><li>錯誤警示</li><li>勝利慶祝</li></ul><p>可在 <strong>設定 → 音效</strong> 中開啟或關閉音效。</p><h2 id="技巧與訣竅" tabindex="-1">技巧與訣竅 <a class="header-anchor" href="#技巧與訣竅" aria-label="Permalink to “技巧與訣竅”">​</a></h2><ul><li><strong>從已知的線索開始</strong>——先掃描已經填了不少數字的列、欄與區塊。</li><li><strong>善用鉛筆筆記</strong>——在困難、專家與大師難度特別有幫助。</li><li><strong>尋找裸單數</strong>——如果某個格子只有一個候選數字，就把它填進去。</li><li><strong>尋找隱藏單數</strong>——如果某個數字在同一列／欄／區塊中只能放在一個位置，就填在那裡。</li><li><strong>節制使用提示</strong>——提示很適合學習，但不靠提示完成一道題目更有成就感。</li><li><strong>累積每日連續天數</strong>——每日挑戰是養成穩定練習習慣的好方法。</li></ul>`,48)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};